"use client";

/**
 * What the import did, once it is over.
 *
 * The two files are reported separately and reconciled separately, because they
 * genuinely can disagree: a member can be matched to somebody who already
 * exists while their loans still fail on a product that has no mapping. Summing
 * the two into one set of tiles would hide exactly the case an admin has to act
 * on.
 *
 * The error list and its download live in ./import-errors-table — the report is
 * generated by the server on purpose, because this screen holds one page of
 * issues and a CSV built from that is a short file that looks complete.
 */

import { useMemo } from "react";
import { AlertTriangle, Ban, CheckCircle2, RotateCcw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { cn } from "@/lib/utils";
import type { ImportFileKind } from "@/types/data-import";
import { useImportStatus } from "../_hooks/use-import-status";
import { ImportErrorsTable } from "./import-errors-table";
import { OutcomeTiles } from "./outcome-tiles";
import { phaseLabel } from "./step-processing";

const KIND_ORDER: readonly ImportFileKind[] = ["customers", "loans"];

export interface StepResultProps {
  runId: number;
  /** Clear this run out of the wizard and open a fresh one. */
  onStartOver: () => void;
  className?: string;
}

export function StepResult({ runId, onStartOver, className }: StepResultProps) {
  // The poll stops the moment the server reports `is_closed`, so a finished run
  // costs exactly one request.
  const { status, loading, error } = useImportStatus({ runId });

  const files = useMemo(
    () => KIND_ORDER.map((kind) => ({ kind, block: status?.files?.[kind] })).filter((entry) => entry.block),
    [status],
  );

  if (!status) {
    return (
      <div className={cn("rounded-lg border p-6", className)}>
        {loading ? (
          <p className="flex items-center gap-2 text-sm text-muted-foreground">
            <Spinner />
            Reading the result…
          </p>
        ) : (
          <p role="alert" className="text-sm text-muted-foreground">
            {error ?? "This import could not be read."}
          </p>
        )}
      </div>
    );
  }

  // Presentation only, and every branch has a safe default: a phase nobody here
  // recognises falls through to the neutral wording rather than to the icon for
  // "cancelled".
  const failed = status.phase === "failed";
  const cancelled = status.phase === "cancelled";
  const settledWell = !failed && !cancelled;

  return (
    <div className={cn("space-y-8", className)}>
      <header
        className={cn(
          "flex items-start gap-3 rounded-lg border p-4",
          settledWell && status.is_closed && "border-green-500/40 bg-green-500/10",
          failed && "border-red-500/40 bg-red-500/10",
          cancelled && "border-border bg-muted/40",
        )}
      >
        {failed ? (
          <AlertTriangle className="mt-0.5 size-5 shrink-0 text-red-600" aria-hidden="true" />
        ) : cancelled ? (
          <Ban className="mt-0.5 size-5 shrink-0 text-muted-foreground" aria-hidden="true" />
        ) : (
          <CheckCircle2 className="mt-0.5 size-5 shrink-0 text-green-600" aria-hidden="true" />
        )}
        <div>
          <h2 className="font-heading text-lg font-medium">{phaseLabel(status.phase)}</h2>
          <p className="mt-0.5 text-sm text-muted-foreground">
            {/* `failure_reason` is shown verbatim and never parsed — it is a
                fixed operator-facing string, not a description of a row. */}
            {failed
              ? (status.failure_reason ??
                "The import stopped before it finished. Nothing further will be written.")
              : cancelled
                ? (status.failure_reason ??
                  "This import was cancelled before anything was written to your members or loans.")
                : status.is_closed
                  ? "Every row in both files has been decided. The figures below account for all of them."
                  : "This import is still running. The figures below are what has been decided so far."}
          </p>
        </div>
      </header>

      <div className="space-y-8">
        {files.map(({ kind, block }) => (
          <OutcomeTiles
            key={kind}
            kind={kind}
            counts={block!.counts}
            filename={
              (block as { original_filename?: string } | undefined)?.original_filename ?? null
            }
            runClosed={status.is_closed}
          />
        ))}
      </div>

      <p className="text-sm text-muted-foreground">
        The two files are counted separately on purpose. A member can be matched
        to somebody who already existed while their loans still fail — so each
        file&apos;s figures add up on their own, and neither total explains the
        other.
      </p>

      <ImportErrorsTable
        runId={runId}
        reportAvailable={status.error_report_available}
        rowsWithErrors={status.rows_with_errors}
      />

      <div className="flex flex-wrap gap-2 border-t pt-4">
        <Button variant="outline" onClick={onStartOver}>
          <RotateCcw />
          Start another import
        </Button>
      </div>
    </div>
  );
}
